ALTER TABLE public.receipt_legacy_sources ADD COLUMN IF NOT EXISTS canonical_receipt_id uuid REFERENCES public.receipts(id);
CREATE OR REPLACE FUNCTION public.resolve_legacy_receipt_link(_source uuid,_resolution text,_canonical uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.receipt_legacy_sources;r public.receipts;BEGIN PERFORM pg_advisory_xact_lock(60412026,6);PERFORM public.finance_assert_writer();PERFORM public._assert_reason(_reason);SELECT * INTO s FROM public.receipt_legacy_sources WHERE id=_source FOR UPDATE;IF NOT FOUND OR s.resolution<>'review' OR _resolution NOT IN('distinct','duplicate') THEN RAISE EXCEPTION 'المصدر أو قرار المراجعة غير صالح';END IF;IF _resolution='duplicate' THEN SELECT * INTO r FROM public.receipts WHERE id=_canonical;IF NOT FOUND OR r.id=s.receipt_id OR r.archived_at IS NOT NULL OR r.party_id IS DISTINCT FROM (SELECT party_id FROM public.receipts WHERE id=s.receipt_id) OR r.amount_excl_vat<>s.rounded_amount OR NOT EXISTS(SELECT 1 FROM public.receipt_legacy_sources WHERE receipt_id=r.id AND resolution='distinct') THEN RAISE EXCEPTION 'الإيصال المرجعي يجب أن يكون معتمدًا لنفس العميل والمبلغ';END IF;END IF;UPDATE public.receipt_legacy_sources SET resolution=_resolution,canonical_receipt_id=CASE WHEN _resolution='duplicate' THEN _canonical ELSE receipt_id END,resolution_reason=_reason,resolved_by=auth.uid(),resolved_at=now() WHERE id=s.id;PERFORM public.finance_audit('LEGACY_SOURCE_REVIEWED','receipt_legacy_sources',s.id,to_jsonb(s),(SELECT to_jsonb(x) FROM public.receipt_legacy_sources x WHERE id=s.id),_reason);END $$;
REVOKE ALL ON FUNCTION public.resolve_legacy_receipt_link(uuid,text,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.resolve_legacy_receipt_link(uuid,text,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.resolve_legacy_receipt(_source uuid,_resolution text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _resolution='duplicate' THEN RAISE EXCEPTION 'حدد الإيصال المرجعي عند مراجعة التكرار';END IF;PERFORM public.resolve_legacy_receipt_link(_source,_resolution,NULL,_reason);END $$;
CREATE OR REPLACE VIEW public.finance_source_integrity WITH(security_invoker=true) AS WITH live AS(SELECT 'unit_collections'::text AS source_table,id AS source_id,amount AS original_amount,is_archived AS source_archived,created_at AS source_recorded_at,unit_id FROM public.unit_collections UNION ALL SELECT 'invoices',id,paid_amount,archived_at IS NOT NULL,coalesce(paid_at,created_at),unit_id FROM public.invoices WHERE paid_amount<>0) SELECT coalesce(l.source_table,s.source_table) AS source_table,coalesce(l.source_id,s.source_id) AS source_id,l.source_id IS NULL AS missing_source,s.id IS NULL AS missing_mapping,(l.original_amount IS DISTINCT FROM s.original_amount OR l.source_archived IS DISTINCT FROM s.source_archived OR l.unit_id IS DISTINCT FROM s.unit_id OR l.source_recorded_at IS DISTINCT FROM s.source_recorded_at) AS changed_source FROM live l FULL JOIN public.receipt_legacy_sources s USING(source_table,source_id);
GRANT SELECT ON public.finance_source_integrity TO authenticated,service_role;
CREATE OR REPLACE VIEW public.receipt_cash_read WITH(security_invoker=true) AS SELECT r.* FROM public.receipts r WHERE r.archived_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.receipt_legacy_sources s WHERE s.receipt_id=r.id AND s.resolution<>'distinct');
GRANT SELECT ON public.receipt_cash_read TO authenticated,service_role;
CREATE OR REPLACE VIEW public.installments_read WITH(security_invoker=true) AS SELECT i.*,CASE WHEN i.status NOT IN('paid','waived') AND i.due_date<current_date THEN 'overdue' ELSE i.status END AS current_status FROM public.installments i;
GRANT SELECT ON public.installments_read TO authenticated,service_role;
SELECT count(*) FILTER(WHERE missing_source OR missing_mapping OR changed_source) AS integrity_issues FROM public.finance_source_integrity;